import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.Bogozrur.js";const c=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function r(o,e,l,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to Jengo, the premium ecosystem for rapid CodeIgniter 4 development.</p><p>Jengo is designed to provide a modern, &quot;Breeze-like&quot; experience for CI4, coming out of the box with everything you need to build robust, modern web applications.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before installing Jengo, ensure your local environment meets the following requirements:</p><ul><li><strong>PHP 8.2</strong> or higher</li><li><strong>Composer</strong> (Globally installed)</li><li><strong>Node.js &amp; npm/pnpm/yarn</strong> (For frontend assets)</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The best way to start a new Jengo project is by using the official Jengo Installer. Install it globally via Composer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jengo/installer</span></span></code></pre></div><blockquote><p><strong>Note:</strong> Make sure your global Composer <code>bin</code> directory is in your system&#39;s <code>PATH</code>.</p></blockquote><h2 id="creating-your-first-app" tabindex="-1">Creating Your First App <a class="header-anchor" href="#creating-your-first-app" aria-label="Permalink to &quot;Creating Your First App&quot;">​</a></h2><p>Once the installer is available, you can bootstrap a new application simply by running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jengo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The interactive installer will guide you through the process, asking for your preferred starter kit, package manager, and whether you&#39;d like to include Authentication and API suites.</p><h2 id="starting-the-development-server" tabindex="-1">Starting the Development Server <a class="header-anchor" href="#starting-the-development-server" aria-label="Permalink to &quot;Starting the Development Server&quot;">​</a></h2><p>Jengo heavily utilizes <strong>Vite</strong> for blazing-fast frontend development.</p><p>Navigate to your new project and start the PHP server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>In a separate terminal, start the Vite development server to enable Hot Module Replacement (HMR):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>You can now access your application in the browser!</p>`,21)])])}const u=t(n,[["render",r]]);export{c as __pageData,u as default};
